∀ {k : Type u_1} {A : Type u_2} [inst : CommRing.{u_1} k] [inst_1 : Ring.{u_2} A] [inst_2 : Algebra.{u_1, u_2} k A]
  (a : A) (f : Etingof.Coregular.{u_1, u_2} k A) (b : A),
  Eq.{u_1 + 1}
    (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), u_2 + 1, u_1 + 1}
      (DFunLike.coe.{max (u_2 + 1) (u_1 + 1), max (u_2 + 1) (u_1 + 1), max (u_2 + 1) (u_1 + 1)}
        Etingof.Coregular.toDual.{u_1, u_2} (HSMul.hSMul.{u_2, max u_1 u_2, max u_1 u_2} a f))
      b)
    (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), u_2 + 1, u_1 + 1}
      (DFunLike.coe.{max (u_2 + 1) (u_1 + 1), max (u_2 + 1) (u_1 + 1), max (u_2 + 1) (u_1 + 1)}
        Etingof.Coregular.toDual.{u_1, u_2} f)
      (HMul.hMul.{u_2, u_2, u_2} b a))
